<style>
    .tkt-hst-info-card {
        background: #EFF2FA;
        border-radius: 8px;
    }

    [data-bs-theme=dark] .tkt-hst-info-card {
        background: #1D1D1D;
        border: 1px solid #2A2A2D;
    }

    .tkt-hst-badge {
        width: 36px;
        height: 36px;
        font-size: 8px;
        line-height: 1.3;
    }

    .tkt-hst-badge.green {
        background: #186B43;
    }

    .tkt-hst-badge.purple {
        background: #5C00E5;
    }

    .tkt-hst-connector-line {
        width: 1px;
        background: #DFDFE1;
        flex: 1;
        min-height: 36px;
        align-self: center;
    }

    [data-bs-theme=dark] .tkt-hst-connector-line {
        background: #2A2A2D;
    }

    .tkt-hst-timeline-wrap {
        border-top: 1px solid #F0F0F0;
        max-height: 250px;
        overflow-y: auto;
    }

    [data-bs-theme=dark] .tkt-hst-timeline-wrap {
        border-top: 1px solid #2A2A2D;
    }

    .tkt-hst-card {
        border: 1px solid #F0F0F0;
        border-left: 6px solid #7F7F7F;
        border-radius: 6px;
        padding: 10px 14px;
    }

    [data-bs-theme=dark] .tkt-hst-card {
        border-color: #2A2A2D;
        border-left-color: #7F7F7F;
    }

    .tkt-hst-avatar {
        width: 20px;
        height: 20px;
        background: #e0e0e0;
    }

    .tkt-hst-timeline-item {
        margin-bottom: 8px;
    }

    .tkt-hst-timeline-item:last-child {
        margin-bottom: 0px;
    }

    .tkt-hst-timeline-item:last-child .tkt-hst-connector-line {
        display: none;
    }
</style>
